python -c "
import json

with open('/app/output/solution.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

print('=== High Confidence Matches ===')
count = 0
for rec in data['records']:
    for seg in rec['normalized']:
        if seg['pred_code'] != 'UNKNOWN' and seg['confidence'] >= 0.7:
            print(f\"\\nRaw: {seg['span_text'][:80]}...\")
            print(f\"Match: {seg['pred_code']} - {seg['pred_label'][:60]}...\")
            print(f\"Confidence: {seg['confidence']}\")
            count += 1
            if count >= 5:
                break
    if count >= 5:
        break

print('\\n=== Unknown (Low Confidence) Examples ===')
count = 0
for rec in data['records']:
    for seg in rec['normalized']:
        if seg['pred_code'] == 'UNKNOWN':
            print(f\"\\nRaw: {seg['span_text'][:80]}...\")
            print(f\"Rationale: {seg['rationale'][:100]}...\")
            print(f\"Confidence: {seg['confidence']}\")
            count += 1
            if count >= 3:
                break
    if count >= 3:
        break
"
